// One visual per shot in shots.json (each 2 s or less), matching what is said at that moment.
// The descent is one continuous ocean (Water) whose light, life and depth counter follow the narration;
// it rotates with real footage, real photos (NOAA, US Navy, Commons) and diagrams.
import React from "react";
import { Img, staticFile } from "remotion";
import { FONT } from "../kit/ui";
import { MONO } from "../kit/hud";
import { registerKind } from "../kit/edit-rules";
import { BarsShot, ListShot, MapShot, NumShot, StampShot, TitleShot } from "../kit/shots";
import { C } from "../kit/theme";
import { Callout, FX, Insert, Parallax } from "../kit/vfx";
import { Kicker } from "../kit/shots";
import { Card, Column, Diagram, Fingertip, FromBelow, SizeCompare, Tmao, Water, type Actor } from "./draw";
import { Diver } from "../humpback/draw";

const V: React.FC<{ id: string; t?: number; label?: string; under?: boolean; rays?: boolean; snow?: boolean; bubbles?: boolean }> = ({ id, t = 0, ...rest }) => (
  <FX src={`footage/mariana/v${id}_${t}.mp4`} {...rest} />
);
const P: React.FC<{ n: string; credit: string; sx?: number; sy?: number; sr?: number; dir?: number; under?: boolean; snow?: boolean }> = ({ n, ...rest }) => (
  <Parallax src={`photos/mariana/${n}.jpg`} {...rest} />
);
registerKind("footage", V);
registerKind("photo", P);
const K: React.FC<{ text: string; color?: string; size?: number; y?: number }> = ({ text, color, size = 84, y = 170 }) => <Kicker text={text} color={color} size={size} y={y} align="center" x={0} width={1920} />;
// A real photo inset over the dark water at a given depth.
const Over: React.FC<{ photo: string; name: string; credit: string; d?: number; shape?: "circle" | "rect"; size?: number }> = ({ photo, name, credit, d = 600, shape = "rect", size = 400 }) => (
  <Water d0={d}>
    <Insert photo={`photos/mariana/${photo}.jpg`} name={name} credit={credit} shape={shape} x={shape === "rect" ? 960 - size * 0.675 : 960 - size / 2} y={150} size={size} />
  </Water>
);
registerKind("drawn", Over);
// A wide specimen photo shown whole, framed, on the water at a depth.
const Wide: React.FC<{ photo: string; name: string; credit: string; d?: number }> = ({ photo, name, credit, d = 8000 }) => (
  <Water d0={d}>
    <div style={{ position: "absolute", left: 310, top: 110, width: 1300, textAlign: "center" }}>
      <Img src={staticFile(`photos/mariana/${photo}.jpg`)} style={{ width: 1300, borderRadius: 18, border: "7px solid #f4f8fa", boxShadow: "0 18px 50px rgba(0,0,0,0.65)" }} />
      <div style={{ marginTop: 14, fontFamily: FONT, fontWeight: 800, fontSize: 40, color: "#f4f8fa", textShadow: "0 6px 24px rgba(0,0,0,0.9)" }}>{name}</div>
      <div style={{ fontFamily: MONO, fontWeight: 700, fontSize: 16, letterSpacing: 2, color: "rgba(255,255,255,0.7)" }}>{credit}</div>
    </div>
  </Water>
);
registerKind("photo", Wide);

const A = (c: Actor["c"], x0: number, y0: number, o: Partial<Actor> = {}): Actor => ({ c, x0, y0, ...o });
